    "body": "French counts 70 as soixante-dix (60 + 10), 80 as quatre-vingts (4 × 20) and 90 as quatre-vingt-dix (4 × 20 + 10). So 89 is quatre-vingt-neuf and 75 is soixante-quinze. Percentages: vingt pour cent.",
